set -uo pipefail
PROJ=/srv/wizard/project
DST="$PROJ/scripts/programming_curriculum_supervisor.py"
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
WANT=a665138c0c0171ce100945de365ecd3eebf383d7fd35c25966201482cc0e7dbb

# The supervisor is the only changed file that runs ON the host; the watcher
# and the admission watchdog both run locally and probe over SSM.
#
# Deliberately does NOT restart. `deferred-replay-active.json` is state:training
# at row 223,240 of an interval starting at 201,344, and on startup
# `recover_interrupted_deferred_replay` rolls any non-admitted marker back to
# its start -- so restarting here destroys ~21,900 durable rows for a fix that
# changes nothing about whether this interval can finish. The running
# generation keeps them; the next start picks the fix up.
cat >/tmp/sup.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/sup.b64 | gunzip -c >/tmp/sup.py || { echo 'DEPLOYJSON {"error":"decode failed"}'; exit 0; }
GOT=$(sha256sum /tmp/sup.py | awk '{print $1}')
if [ "$GOT" != "$WANT" ]; then
  echo "DEPLOYJSON {\"error\":\"sha mismatch\",\"got\":\"$GOT\"}"; exit 0
fi

BEFORE_SHA=$(sha256sum "$DST" 2>/dev/null | awk '{print $1}')
BEFORE_INO=$(stat -c %i "$DST" 2>/dev/null)
cp -p "$DST" "$PROJ/scripts/.supervisor.bak-$STAMP" 2>/dev/null
install -m 0644 /tmp/sup.py "$DST"
# SSM writes land root:root and the supervisor runs as ec2-user.
chown 1000:1000 "$DST"
AFTER_SHA=$(sha256sum "$DST" | awk '{print $1}')
AFTER_INO=$(stat -c %i "$DST")

# "Deploy is not load": prove the deployed copy PARSES and carries the fix
# rather than trusting that a byte-identical copy behaves.
python3 -c "
import ast, json
src = open('$DST', encoding='utf-8').read()
names = {n.name for n in ast.walk(ast.parse(src)) if isinstance(n, ast.FunctionDef)}
print('PARSEJSON ' + json.dumps({
    'parses': True,
    'has_reclaim_fn': 'reclaim_disk_for_floor' in names,
    'has_named_state': 'disk_exhausted_unrecoverable' in src,
    'reclaim_call_sites': src.count('reclaim_disk_for_floor'),
    'has_max_attempts': 'MAX_DISK_RECLAIM_ATTEMPTS' in src,
}))
" 2>&1 | tail -2

echo "DEPLOYJSON {\"before_sha\":\"$BEFORE_SHA\",\"after_sha\":\"$AFTER_SHA\",\"before_inode\":\"$BEFORE_INO\",\"after_inode\":\"$AFTER_INO\",\"restarted\":false}"
echo "FREE_BYTES $(df -B1 --output=avail /srv/wizard | tail -1)"
echo -n "STATUS "; tail -c 400 /srv/wizard/runtime/programming-integrated-20260713/curriculum-supervisor.status.json
